import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] suffixArray(String s) {
        int n = s.length();
        long m = n + 130;
        int[] rk = new int[n];
        int[] nr = new int[n];
        int[] sa = new int[n];
        long[] packed = new long[n];
        for (int i = 0; i < n; i++) rk[i] = s.charAt(i);
        for (int k = 1; ; k *= 2) {
            for (int i = 0; i < n; i++) {
                long key = (rk[i] + 1) * m + (i + k < n ? rk[i + k] + 1 : 0);
                packed[i] = (key << 15) | i;
            }
            Arrays.sort(packed);
            for (int j = 0; j < n; j++) sa[j] = (int) (packed[j] & 32767);
            nr[sa[0]] = 0;
            for (int j = 1; j < n; j++) nr[sa[j]] = nr[sa[j - 1]] + ((packed[j] >> 15) != (packed[j - 1] >> 15) ? 1 : 0);
            int[] t = rk;
            rk = nr;
            nr = t;
            if (rk[sa[n - 1]] == n - 1) break;
        }
        return sa;
    }

    static int[] lcpArray(String s, int[] sa) {
        int n = s.length();
        int[] rk = new int[n];
        int[] lcp = new int[n];
        for (int i = 0; i < n; i++) rk[sa[i]] = i;
        int h = 0;
        for (int i = 0; i < n; i++) {
            if (rk[i] > 0) {
                int j = sa[rk[i] - 1];
                while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;
                lcp[rk[i]] = h;
                if (h > 0) h--;
            } else {
                h = 0;
            }
        }
        return lcp;
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int len = s.length();
        int[] sa = suffixArray(s);
        int[] lcp = lcpArray(s, sa);
        int[] rk = new int[len];
        for (int i = 0; i < len; i++) rk[sa[i]] = i;
        int levels = 1;
        while ((1 << levels) <= len) levels++;
        int[][] table = new int[levels][];
        table[0] = lcp;
        for (int lv = 1; lv < levels; lv++) {
            int k = 1 << (lv - 1);
            int size = len - 2 * k + 1;
            table[lv] = new int[Math.max(size, 0)];
            for (int x = 0; x < size; x++) table[lv][x] = Math.min(table[lv - 1][x], table[lv - 1][x + k]);
        }
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            int i = (int) qs[t][0] - 1, j = (int) qs[t][1] - 1;
            if (t > 0) out.append(" ");
            if (i == j) {
                out.append(len - i);
                continue;
            }
            int a = rk[i], b = rk[j];
            if (a > b) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            int lo = a + 1;
            int span = b - lo + 1;
            int level = 31 - Integer.numberOfLeadingZeros(span);
            out.append(Math.min(table[level][lo], table[level][b - (1 << level) + 1]));
        }
        System.out.println(out);
    }
}
